CREATE     PROCEDURE [synapse_fo].[usp_Insert_TRANSPORTATIONDOCUMENT]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:02
	Description: Insert stored procedure for TRANSPORTATIONDOCUMENT from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[TRANSPORTATIONDOCUMENT]
	(
		[CARRIERCODE],
		[CARRIERTYPE],
		[CREATEDBY],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DOCUMENTDATETIME],
		[DOCUMENTDATETIMETZID],
		[DOPRINTTRANSPORTATIONDOCUMENT],
		[DROPOFFMODE_MX],
		[DROPOFFSPOT_MX],
		[ECONOMICACTIVITYTYPE],
		[ENVIRONMENTALDAMAGEINSURANCEPOLICYNUM_MX],
		[ENVIRONMENTALDAMAGEINSURANCEVENDOR_MX],
		[FileName],
		[ISSUEDBY],
		[LastProcessedChange_DateTime],
		[LINEID],
		[LOADEDADDRESSNAME],
		[LOADEDDATETIME],
		[LOADEDDATETIMETZID],
		[LOADEDPOSTALADDRESS],
		[LSN],
		[PACKAGEDANGERDEGREE],
		[PACKAGEDESCRIPTION],
		[PARTITION],
		[PICKUPMODE_MX],
		[PICKUPSPOT_MX],
		[RECID],
		[RECVERSION],
		[SATPERMISSIONID_MX],
		[SATPERMISSIONTYPE_MX],
		[SysRowId],
		[TRAVELDISTANCE_MX],
		[TRAVELTIME_MX],
		[UNLOADEDADDRESSNAME],
		[UNLOADEDDATETIME],
		[UNLOADEDDATETIMETZID],
		[UNLOADEDPOSTALADDRESS],
		[WEIGHTUNIT_MX]
	)
	SELECT 
		stg.[CARRIERCODE],
		stg.[CARRIERTYPE],
		stg.[CREATEDBY],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DOCUMENTDATETIME],
		stg.[DOCUMENTDATETIMETZID],
		stg.[DOPRINTTRANSPORTATIONDOCUMENT],
		stg.[DROPOFFMODE_MX],
		stg.[DROPOFFSPOT_MX],
		stg.[ECONOMICACTIVITYTYPE],
		stg.[ENVIRONMENTALDAMAGEINSURANCEPOLICYNUM_MX],
		stg.[ENVIRONMENTALDAMAGEINSURANCEVENDOR_MX],
		stg.[FileName],
		stg.[ISSUEDBY],
		stg.[LastProcessedChange_DateTime],
		stg.[LINEID],
		stg.[LOADEDADDRESSNAME],
		stg.[LOADEDDATETIME],
		stg.[LOADEDDATETIMETZID],
		stg.[LOADEDPOSTALADDRESS],
		stg.[LSN],
		stg.[PACKAGEDANGERDEGREE],
		stg.[PACKAGEDESCRIPTION],
		stg.[PARTITION],
		stg.[PICKUPMODE_MX],
		stg.[PICKUPSPOT_MX],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[SATPERMISSIONID_MX],
		stg.[SATPERMISSIONTYPE_MX],
		stg.[SysRowId],
		stg.[TRAVELDISTANCE_MX],
		stg.[TRAVELTIME_MX],
		stg.[UNLOADEDADDRESSNAME],
		stg.[UNLOADEDDATETIME],
		stg.[UNLOADEDDATETIMETZID],
		stg.[UNLOADEDPOSTALADDRESS],
		stg.[WEIGHTUNIT_MX]	
	FROM [staging_fo].[TRANSPORTATIONDOCUMENT] stg
		LEFT JOIN [synapse_fo].[TRANSPORTATIONDOCUMENT] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
